CREATE TABLE "assessments_drive" ("id" uuid NOT NULL PRIMARY KEY, "name" varchar(255) NOT NULL, "code" varchar(64) NOT NULL UNIQUE, "description" text NOT NULL, "status" varchar(20) NOT NULL, "visibility" varchar(20) NOT NULL, "start_date" timestamp with time zone NULL, "end_date" timestamp with time zone NULL, "registration_start" timestamp with time zone NULL, "registration_end" timestamp with time zone NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL, "created_by_id" bigint NULL);;
