CREATE TABLE "assessments_driveassessment" ("id" uuid NOT NULL PRIMARY KEY, "display_order" integer NOT NULL CHECK ("display_order" >= 0), "is_required" boolean NOT NULL, "registration_enabled" boolean NOT NULL, "created_at" timestamp with time zone NOT NULL, "assessment_id" uuid NOT NULL, "drive_id" uuid NOT NULL);;
CREATE TABLE "assessments_driveinvitation" ("id" uuid NOT NULL PRIMARY KEY, "token_hash" varchar(128) NOT NULL, "access_code" varchar(32) NULL, "label" varchar(120) NOT NULL, "expires_at" timestamp with time zone NULL, "max_uses" integer NULL CHECK ("max_uses" >= 0), "usage_count" integer NOT NULL CHECK ("usage_count" >= 0), "is_active" boolean NOT NULL, "created_at" timestamp with time zone NOT NULL, "created_by_id" bigint NULL, "drive_id" uuid NOT NULL);;
CREATE TABLE "assessments_driveregistration" ("id" uuid NOT NULL PRIMARY KEY, "registration_status" varchar(20) NOT NULL, "registration_source" varchar(20) NOT NULL, "notes" text NOT NULL, "registered_at" timestamp with time zone NOT NULL, "candidate_id" uuid NOT NULL, "drive_id" uuid NOT NULL);;
